// Project polygon vertices onto the plane
std::vector<Kernel::Point_3> projected_points;
for (const auto& coord : polygon_coords) {
    if (coord.size() < 3) continue; // Skip invalid points
    Kernel::Point_3 p(coord[0], coord[1], coord[2]);
    projected_points.push_back(Kernel::Projection_traits<Kernel>::projection(p, plane));
}

// Insert points into triangulation
std::vector<Triangulation::Point> points;
for (const auto& pt : projected_points) {
    points.push_back(Triangulation::Point(pt));
}

Triangulation::Point_location location = triangulation.locate(points[0]);
Triangulation::Face_handle fh = location.first;
Triangulation::Vertex_handle vh = triangulation.insert(points[0], fh);

for (std::size_t i = 1; i < points.size(); ++i) {
    Triangulation::Vertex_handle new_vh = triangulation.insert(points[i], walk_start);
    triangulation.insert_constraint(vh, new_vh);
    vh = new_vh;
}

// Close the polygon by adding constraint between last and first vertex
if (!points.empty()) {
    triangulation.insert_constraint(vh, points[0]);
}

// Set walk_start to the first face of the polygon for future operations
if (!triangulation.is_valid(walk_start)) {
    walk_start = triangulation.finite_faces_begin();
}
// END_CODE

